sp() { awk '
{
  if ($0 ~ /^[[:space:]]*```/) { infence = !infence; next }
  if (infence) next
  stripped = $0
  sub(/^[[:space:]]*[#>*|`_-]*[[:space:]]*/, "", stripped)
  if (stripped ~ /^[Mm]odalit[aà][[:space:]]*:/) {
    found = 1
    if (stripped ~ /^[Mm]odalit[aà][[:space:]]*:[[:space:]]*\*{0,2}`{0,1}[[:space:]]*[Pp]iena[[:space:]]*`{0,1}\*{0,2}[[:space:]]*$/) {
      ok = 1
    } else if (stripped ~ /^[Mm]odalit[aà][[:space:]]*:[[:space:]]*\*{0,2}`{0,1}[[:space:]]*[Rr]idotta.*[Mm]issing:[[:space:]]*(rule-librar[a-z]*|decisions|glossary|graph-verif[a-z]*)([,[:space:]]+(rule-librar[a-z]*|decisions|glossary|graph-verif[a-z]*))*[[:space:]]*$/) {
      ok = 1
    } else {
      bad = 1
    }
  }
}
END { if (found != 1 || bad == 1) exit 1; exit 0 }
' "$1"; }; test -z "$RECORD" || { for f in reversibilit opzioni 'costo per opzione' scelta enforcement 'verifica di chiusura' prossimo ASSUMED; do grep -qi "$f" "$RECORD" || exit 1; done; sp "$RECORD" || exit 1; }; test -z "$LANDING" || { for f in call_sites prerequisites closure_check; do grep -qi "$f" "$LANDING" || exit 1; done; sp "$LANDING" || exit 1; }; test -z "$ARCHITECTURE_DOC" || { for f in schema_version document_type snapshot_ref snapshot_scope review_trigger; do grep -qi "$f" "$ARCHITECTURE_DOC" || exit 1; done; sp "$ARCHITECTURE_DOC" || exit 1; }; test -z "$AUDIT_REPORT" || { for f in scope perimetro strumentazione; do grep -qi "$f" "$AUDIT_REPORT" || exit 1; done; sp "$AUDIT_REPORT" || exit 1; }
